// prompt-buttons (Claude Codex Custom Buttons): a row of buttons above the prompt box (Continue,
// Regenerate and the user's own buttons), plus /c, /r and /btn.
// Data comes from the plugin's bundled ccb-mcp server; shared rules come from the
// vendored core (./core, generated by scripts/build-plugin.mjs). Never logs prompt text.
import { atom, read, update } from "claude-code";
import type { EngineInterface, Register } from "claude-code";

import type { ButtonView, ClientState, UndoState } from "../types";
import {
  DEFAULT_CONTINUE_MESSAGE,
  buildRefineRequest,
  cleanRefineOutput,
  dateBuiltIns,
  expand,
  missingFragments,
} from "./core/index.js";
import { bankText, listedPrompt, openBank, registerBank, saveDraftAsPrompt, syncNow, usePrompt } from "./bank.js";
import { readClient, refreshClient } from "./client.js";
import { openTranslate, registerTranslate, startInstant, translateBubble, translateCommand } from "./translate.js";
import { builtIns as contextValues, callTool, lastUserMessage } from "./mcp.js";
import { appendToNote, noteText, notesText, openNotes, refreshOpenNote, registerNotes } from "./notes.js";

export const PLUGIN = "prompt-buttons";
const UNDO_MS = 30_000;
/** A "busy" mark older than this is left over from a reload or a lost worker, and ignored. */
const BUSY_STALE_MS = 120_000;
const MAX_REWRITE_TOKENS = 4000;

const truncated = atom({ plugin: "prompt-buttons", key: "truncated" } as const, false);
const undo = atom({ plugin: "prompt-buttons", key: "undo" } as const, null);
const busy = atom({ plugin: "prompt-buttons", key: "busy" } as const, null);

type $ = EngineInterface;

/**
 * How a message is sent. A button press submits at once. A slash command can't: its
 * hook holds the turn a submit would wait on, so the engine refuses a submit made
 * inside it. Commands queue the text and send it from a timer, after the hook has
 * returned. Anything still queued then (if a submit was refused) is sent when the main
 * conversation's next turn completes. Messages go out in the order they were queued.
 */
export type Send = (text: string) => Promise<void>;
const pending: string[] = [];
let flushing = false;

async function flushPending($: $): Promise<void> {
  if (flushing) return;
  flushing = true;
  try {
    while (pending.length > 0) {
      const text = pending[0] as string;
      try {
        await $.prompt.submit({ text });
      } catch {
        return; // keep it for the next completed turn
      }
      pending.shift();
    }
  } finally {
    flushing = false;
  }
}

const sendNow =
  ($: $): Send =>
  async (text) => {
    await $.prompt.submit({ text });
  };
const sendAfterCommand =
  ($: $): Send =>
  async (text) => {
    pending.push(text);
    $.clock.after(0, () => flushPending($));
  };

// --- actions --------------------------------------------------------------------------

/** The sync button: opens the Prompt Bank when something needs doing there, else syncs now. */
async function syncPressed($: $, state: string, conflicts: number): Promise<void> {
  if (conflicts > 0 || state === "signed-out" || state === "not-set-up" || state === "no-credential-store" || state === "error") {
    await openBank($);
    return;
  }
  $.ui.toast(await syncNow($));
}

export async function continueAction($: $, send: Send = sendNow($)): Promise<void> {
  const state = (await readClient($)) ?? (await refreshClient($));
  await update($, truncated, () => false);
  await send(state?.continueMessage ?? DEFAULT_CONTINUE_MESSAGE);
}

/** Picks the text to rewrite, following the regenerate.source setting. */
async function regenerateSource($: $, source: ClientState["settings"]["regenerate"]["source"]): Promise<{ text: string; draft: string }> {
  const draft = (await $.prompt.read()).text;
  const selection = (await $.ui.selection())?.text ?? "";
  if (source === "selection") return { text: selection.trim() ? selection : "", draft };
  if (source === "draft") return { text: draft.trim() ? draft : "", draft };
  if (source === "last") return { text: await lastUserMessage($), draft };
  if (selection.trim()) return { text: selection, draft };
  if (draft.trim()) return { text: draft, draft };
  return { text: await lastUserMessage($), draft };
}

/** Guards against two Regenerates at once (module memory: a reload starts it afresh). */
let regenerating = false;

export async function regenerateAction($: $, extra?: string, send: Send = sendNow($)): Promise<void> {
  if (regenerating) {
    $.ui.toast("Already working on it...");
    return;
  }
  regenerating = true;
  await update($, busy, () => ({ kind: "regenerate", since: Date.now() }));
  try {
    const state = (await readClient($)) ?? (await refreshClient($));
    const { text: source, draft } = await regenerateSource($, state?.settings.regenerate.source ?? "auto");
    if (source.trim() === "") {
      $.ui.toast("Nothing to regenerate: select text or type a draft.");
      return;
    }
    const request = buildRefineRequest(source, {
      instructions: state?.regenerateInstructions ?? null,
      ...(extra ? { extra } : {}),
    });
    const result = await $.model.complete({
      model: await $.session.model(),
      system: request.system,
      prompt: request.user,
      maxTokens: MAX_REWRITE_TOKENS,
    });
    if (!("text" in result) || typeof result.text !== "string" || result.text.trim() === "") {
      const reason = "reason" in result ? String((result as { reason?: unknown }).reason) : "no reply";
      $.ui.toast(`Regenerate failed (${reason}). Your prompt is unchanged.`);
      return;
    }
    const rewritten = cleanRefineOutput(result.text);
    const missing = missingFragments(source, rewritten);
    if (missing.length > 0) {
      $.ui.toast(`Check the rewrite: it dropped ${missing.slice(0, 3).map((m) => JSON.stringify(m.length > 40 ? `${m.slice(0, 37)}...` : m)).join(", ")}.`);
    }
    if (state?.settings.regenerate.autoSubmit) {
      await send(rewritten); // the prompt box was never changed, so there is nothing to undo
    } else {
      await $.prompt.fill({ text: rewritten, mode: "replace" });
      // $.state hands updaters a copy, so the timer recognises its own Undo by ID.
      const saved: UndoState = { text: draft, id: `${Date.now()}-${Math.random().toString(36).slice(2)}` };
      await update($, undo, () => saved);
      $.clock.after(UNDO_MS, () => update($, undo, (current) => (current?.id === saved.id ? null : current)));
    }
  } finally {
    regenerating = false;
    await update($, busy, () => null);
  }
}

export async function undoAction($: $): Promise<boolean> {
  const saved = await read($, undo);
  if (saved === null) return false;
  await $.prompt.fill({ text: saved.text, mode: "replace" });
  await update($, undo, () => null);
  return true;
}

interface Expanded {
  text: string;
  unanswered: string[];
}

export async function runButton($: $, id: string, send: Send = sendNow($)): Promise<string | undefined> {
  const state = await refreshClient($);
  const wanted = id.trim().toLowerCase();
  const button = state?.buttons.find((b) => b.id === id) ?? state?.buttons.find((b) => b.label.trim().toLowerCase() === wanted);
  if (!button) return `No button "${id}". ${buttonsText(state)}`;
  if (button.targetMissing) {
    $.ui.toast(`"${button.label}" uses a prompt that was deleted. Edit the button to choose another.`);
    return undefined;
  }
  const action = button.action;
  switch (action.type) {
    case "continue":
      await continueAction($, send);
      return undefined;
    case "refine":
      await regenerateAction($, undefined, send);
      return undefined;
    case "insert-prompt": {
      const opts = { ...(action.search !== null ? { search: action.search } : {}), category: action.category };
      return (await openBank($, opts)) ? undefined : bankText($, opts);
    }
    case "open-pane":
      if (action.pane === "notes") return (await openNotes($)) ? undefined : notesText($);
      return (await openBank($)) ? undefined : bankText($);
    case "submit":
    case "fill": {
      const values = await contextValues($, dateBuiltIns(new Date()));
      let expanded: Expanded;
      if ("promptId" in action) {
        const got = await callTool<{ expanded: Expanded }>($, "bank_get", {
          id: action.promptId,
          expand: true,
          builtIns: values,
          markUsed: true,
        });
        expanded = got.expanded;
      } else {
        expanded = expand(action.text, { variables: state?.variables ?? {}, builtIns: values, answers: {} });
      }
      if (action.type === "submit" && expanded.unanswered.length === 0) {
        await send(expanded.text);
      } else {
        await $.prompt.fill({ text: expanded.text, mode: action.type === "fill" ? action.mode : "replace" });
        if (expanded.unanswered.length > 0) {
          $.ui.toast(`Fill in ${expanded.unanswered.map((n) => `{{?${n}}}`).join(", ")}, then send.`);
        }
      }
      return undefined;
    }
  }
}

/** The user's buttons, for a command's output. */
function buttonsText(state: ClientState | null): string {
  const buttons = state?.buttons ?? [];
  if (buttons.length === 0) return "You have no buttons of your own yet.";
  return `Your buttons: ${buttons.map((b) => `\`${b.label}\``).join(", ")}. Run one with \`/btn <name>\`.`;
}

/** What the status line says: the commands that stand in for the buttons where the app draws no row. */
const STATUS_HINT = "Buttons: /c · /r · /t · /p · /n · /btn";

/** The label shown on a user button. */
export function buttonLabel(b: ButtonView): string {
  return b.icon ? `${b.icon} ${b.label}` : b.label;
}

// --- hooks ----------------------------------------------------------------------------

/** Slash commands. "/continue" is built into Claude Code, so Continue is "/c". */
export const COMMANDS = [
  { name: "c", description: "Continue a reply that was cut off." },
  { name: "r", description: "Rewrite your draft or selected text into a clearer prompt.", argumentHint: "[extra instruction | undo]" },
  { name: "btn", description: "Run one of your custom buttons, or list them.", argumentHint: "[button name]" },
  { name: "p", description: "Open the Prompt Bank, search it, use a prompt, save the prompt box as a prompt, or sync now.", argumentHint: "[search | use <n> | send <n> | save <title> | sync]" },
  { name: "n", description: "Open Notes, read one, or add text to the open note.", argumentHint: "[read <n> | text to add]" },
  { name: "t", description: "Translate the selection, your draft, or the text given.", argumentHint: "[to <language>:] [text]" },
] as const;

export const register: Register = (on) => {
  registerBank(on);
  registerNotes(on);
  registerTranslate(on);

  on("command.run", { command: "t" }, async ($, e) => {
    const message = await translateCommand($, e.args);
    return message ? { text: message } : {};
  });

  on("command.run", { command: "p" }, async ($, e) => {
    const args = e.args.trim();
    if (args === "sync") return { text: await syncNow($) };
    const save = /^save(?:\s+(.*))?$/s.exec(args);
    if (save) {
      const message = await saveDraftAsPrompt($, save[1]);
      return message ? { text: message } : {};
    }
    const use = /^(use|send)\s+(\S+)$/.exec(args);
    if (use) {
      const message = await usePrompt($, listedPrompt(use[2] as string), use[1] === "send" ? "send" : "insert", sendAfterCommand($));
      return message ? { text: message } : {};
    }
    const opts = args ? { search: args } : {};
    if (await openBank($, opts)) return {};
    return { text: await bankText($, opts) }; // no pane here (a cloud session)
  });

  on("command.run", { command: "n" }, async ($, e) => {
    const text = e.args.trim();
    if (!text) return (await openNotes($)) ? {} : { text: await notesText($) };
    const readOne = /^read\s+(\S+)$/.exec(text);
    if (readOne) return { text: await noteText($, readOne[1] as string) };
    return { text: await appendToNote($, text) };
  });

  on("session.start", async ($, e, next) => {
    const result = await next(e);
    await update($, busy, () => null); // a fresh session has nothing in progress
    // Registered one by one so a refused name (e.g. one Claude Code ships) can't stop the rest.
    for (const spec of COMMANDS) {
      try {
        await $.command.register(spec);
      } catch {
        // the button row still works without this command
      }
    }
    await refreshClient($);
    $.ui.status(STATUS_HINT); // where the app draws no button row (cloud sessions), the commands are the buttons
    startInstant($); // instant translation watches the selection
    return result;
  });

  on("command.run", { command: "c" }, async ($) => {
    await continueAction($, sendAfterCommand($));
    return {};
  });

  on("command.run", { command: "r" }, async ($, e) => {
    const args = e.args.trim();
    if (args === "undo") {
      return (await undoAction($)) ? {} : { text: "Nothing to undo." };
    }
    await regenerateAction($, args || undefined, sendAfterCommand($));
    return {};
  });

  on("command.run", { command: "btn" }, async ($, e) => {
    const id = e.args.trim();
    if (!id) {
      const state = await refreshClient($);
      return { text: buttonsText(state) };
    }
    const message = await runButton($, id, sendAfterCommand($));
    return message ? { text: message } : {};
  });

  // turn.step streams the reply, so its hook is an async generator: `yield* next(e)`
  // passes every chunk through unchanged and evaluates to the step's result.
  on("turn.step", async function* ($, e, next) {
    const result = yield* next(e);
    if (e.agentId === undefined && result.stopReason === "max_tokens") {
      const state = await readClient($);
      if (state?.settings.continue.highlightOnTruncation ?? true) await update($, truncated, () => true);
    }
    return result;
  });

  on("prompt.submit", async ($, e, next) => {
    await update($, truncated, () => false);
    return next(e);
  });

  on("turn.complete", async ($, e, next) => {
    const result = await next(e);
    // Only the main conversation's own turns: not subagents', and not ones the user stopped.
    if (e.agentId === undefined && !e.isAborted) {
      await flushPending($);
      await refreshClient($);
      await refreshOpenNote($);
    }
    return result;
  });

  on("ui.render", { component: "AbovePrompt" }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e);
    const state = await readClient($);
    const isTruncated = await read($, truncated);
    const saved = await read($, undo);
    const busyMark = await read($, busy);
    const working = busyMark !== null && Date.now() - busyMark.since < BUSY_STALE_MS ? busyMark.kind : null;
    const showBuiltIns = state?.settings.buttons.showBuiltIns ?? true;
    const maxVisible = state?.settings.buttons.maxVisible ?? 6;
    const users = state?.buttons ?? [];
    const bubbleEl = await translateBubble($, e);
    if (!showBuiltIns && users.length === 0 && saved === null && bubbleEl === null) return next(e);

    const visible = users.slice(0, maxVisible);
    const overflow = users.slice(maxVisible);
    const { Box, Button, Select } = $.ui.resolve(e);
    const below = await next(e);

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          {showBuiltIns ? (
            <Button
              key="ccb-continue"
              label={isTruncated ? "Continue (cut off)" : "Continue"}
              {...(isTruncated ? { variant: "primary" as const } : {})}
              onPress={() => continueAction($)}
            />
          ) : null}
          {showBuiltIns ? (
            <Button
              key="ccb-regenerate"
              label={working === "regenerate" ? "Regenerating..." : "Regenerate"}
              onPress={() => regenerateAction($)}
            />
          ) : null}
          {showBuiltIns ? <Button key="ccb-prompts" label="Prompts" onPress={() => openBank($)} /> : null}
          {showBuiltIns ? <Button key="ccb-notes" label="Notes" onPress={() => openNotes($)} /> : null}
          {showBuiltIns ? <Button key="ccb-translate" label="Translate" onPress={() => openTranslate($)} /> : null}
          {showBuiltIns && state?.sync && state.sync.state !== "off" ? (
            <Button
              key="ccb-sync"
              label={state.sync.line}
              {...(state.sync.conflicts || state.sync.state === "signed-out" || state.sync.state === "error" ? { variant: "primary" as const } : { dimColor: true })}
              onPress={() => syncPressed($, state.sync?.state ?? "idle", state.sync?.conflicts ?? 0)}
            />
          ) : null}
          {saved !== null ? <Button key="ccb-undo" label="Undo regenerate" onPress={() => undoAction($)} /> : null}
          {visible.map((b) => (
            <Button
              key={`ccb-btn-${b.id}`}
              label={buttonLabel(b)}
              {...(b.targetMissing ? { dimColor: true } : {})}
              onPress={() => runButton($, b.id)}
            />
          ))}
          {overflow.length > 0 ? (
            <Select
              key="ccb-more"
              label="More"
              value=""
              options={[{ label: `More (${overflow.length})...`, value: "" }, ...overflow.map((b) => ({ label: buttonLabel(b), value: b.id }))]}
              onSelect={(value: string) => {
                if (value !== "") void runButton($, value);
              }}
            />
          ) : null}
        </Box>
        {bubbleEl ?? null}
        {below ?? null}
      </Box>
    );
  });
};
